code_example:
#include <iostream>
#include <mutex>
#include <chrono>
#include <thread>

std::timed_mutex mtx;

void worker_thread() {
  auto tp = std::chrono::system_clock::now() + std::chrono::milliseconds(100);
  if (mtx.try_lock_until(tp)) {
    std::cout << "Acquired lock\n";
    std::this_thread::sleep_for(std::chrono::milliseconds(200));
    mtx.unlock();
  } else {
    std::cout << "Failed to acquire lock\n";
  }
}

int main() {
  std::thread t1(worker_thread);
  std::this_thread::sleep_for(std::chrono::milliseconds(50));
  mtx.lock();
  std::cout << "Main thread acquired lock\n";
  std::this_thread::sleep_for(std::chrono::milliseconds(300));
  mtx.unlock();
  t1.join();
  return 0;
}
